// Small deterministic bundler: Obsidian receives one self-contained main.js.
// No npm installation or runtime relative require is needed on desktop/mobile.
const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const entry = fs.readFileSync(path.join(root, 'main.source.js'), 'utf8');
const helper = fs.readFileSync(path.join(root, 'smart-paper.js'), 'utf8');
const needle = 'const SmartPaper = require("./smart-paper");';
if (entry.split(needle).length !== 2) throw new Error('Expected one smart-paper import in main.source.js');
const bundle = entry.replace(needle, () => `const SmartPaper = (() => {\nconst module = { exports: {} };\n${helper}\nreturn module.exports;\n})();`);
fs.writeFileSync(path.join(root, 'main.js'), '// Generated by scripts/build.cjs; edit main.source.js and smart-paper.js.\n' + bundle);
console.log('Built self-contained main.js');
